+  }
+
+  const width = dataRows[0].length;
+  for (const row of dataRows) {
+    if (row.length !== width) {
+      throw new Error('Ragged markdown table rows are not supported');
+    }
+  }
+
+  return dataRows;
+}
+
+function parseRow(line) {
+  const cells = [];
+  let cell = '';
+  let start = 0;
+  let end = line.length;
+
+  if (line[start] === '|') {
+    start += 1;
+  }
+
+  if (end > start && line[end - 1] === '|' && !isEscaped(line, end - 1)) {
+    end -= 1;
+  }
+
+  for (let index = start; index < end; index += 1) {
+    const char = line[index];
+
+    if (char === '|' && !isEscaped(line, index)) {
+      cells.push(normalizeCell(cell));
+      cell = '';
+      continue;
+    }
+
+    if (char === '\\' && line[index + 1] === '|') {
+      cell += '|';
+      index += 1;
+      continue;
+    }
+
+    cell += char;
+  }
+
+  cells.push(normalizeCell(cell));
+  return cells;
+}
+
+function normalizeCell(cell) {
+  return cell.trim();
+}
+
+function isEscaped(value, index) {
+  let backslashes = 0;
+
+  for (let cursor = index - 1; cursor >= 0 && value[cursor] === '\\'; cursor -= 1) {
+    backslashes += 1;
+  }
+
+  return backslashes % 2 === 1;
+}
+
+function isAlignmentRow(row) {
+  return row.every((cell) => /^:?-{3,}:?$/.test(cell));
 }
